INSERT INTO "normative" ("key", "revision", "payload_json", "updated_at") VALUES ('odm-218-6-019-2016-b33', 1, '{"id":"odm-218-6-019-2016-b33","documentCode":"ОДМ 218.6.019-2016","edition":"2016","clause":"Приложение Б, рисунок Б.33, с. 100","description":"Пример схемы для двухполосной дороги при краткосрочных работах; подпись говорит о зоне более 30 м, рисунок содержит обозначение min 30.","application":"Правило проекта для длины от 30 м. Случай ровно 30 м требует предметной сверки из-за расхождения подписи и размерного обозначения.","sourceUrl":"https://rosavtodor.gov.ru/about/upravlenie-fda/upravlenie-nauchno-tekhnicheskikh-issledovaniy--i-informatsionnykh-tekhnologiy/tekhnicheskoe-regulirovanie/otraslevye-dorozhnye-metodicheskie-dokumenty/14520","reviewStatus":"needs-review","checkedAt":"","reviewer":""}', '2026-09-26T12:00:00.000Z');
INSERT INTO "normative" ("key", "revision", "payload_json", "updated_at") VALUES ('odm-218-6-019-2016-b34', 1, '{"id":"odm-218-6-019-2016-b34","documentCode":"ОДМ 218.6.019-2016","edition":"2016","clause":"Приложение Б, рисунок Б.34, с. 101","description":"Пример схемы для двухполосной дороги при краткосрочных работах; подпись говорит о зоне менее 30 м, рисунок содержит обозначение max 30.","application":"Правило проекта для длины менее 30 м. Условия регулирования движения по интенсивности и видимости следует сверять отдельно.","sourceUrl":"https://rosavtodor.gov.ru/about/upravlenie-fda/upravlenie-nauchno-tekhnicheskikh-issledovaniy--i-informatsionnykh-tekhnologiy/tekhnicheskoe-regulirovanie/otraslevye-dorozhnye-metodicheskie-dokumenty/14520","reviewStatus":"needs-review","checkedAt":"","reviewer":""}', '2026-09-26T12:00:00.000Z');
INSERT INTO "normative" ("key", "revision", "payload_json", "updated_at") VALUES ('gost-r-52289-2019', 1, '{"id":"gost-r-52289-2019","documentCode":"ГОСТ Р 52289-2019","edition":"2019; изменения № 1 и № 2 подлежат сверке","clause":"Раздел 5, в том числе 5.1.19 и 5.2.27","description":"Правила применения технических средств организации дорожного движения; конкретные параметры здесь пока не внесены.","application":"Проверить действующую редакцию и точные пункты перед автоматизацией.","sourceUrl":"https://protect.gost.ru/gost/details/94160176-3252-4e7d-8534-2d172e6aa0de","reviewStatus":"needs-review","checkedAt":"","reviewer":""}', '2026-09-26T12:00:00.000Z');
